INSERT INTO public.artists (slug, name, bio, image_url, cover_url) VALUES
('nova-kestrel','Nova Kestrel','Synth-pop architect building cathedrals out of neon and reverb.','https://picsum.photos/seed/nova-kestrel-artist/600/600','https://picsum.photos/seed/nova-kestrel-cover/1600/600'),
('halcyon-drift','Halcyon Drift','Ambient duo mapping the quiet space between two cities.','https://picsum.photos/seed/halcyon-drift-artist/600/600','https://picsum.photos/seed/halcyon-drift-cover/1600/600'),
('mira-solace','Mira Solace','Soul vocalist with a whisper that fills stadiums.','https://picsum.photos/seed/mira-solace-artist/600/600','https://picsum.photos/seed/mira-solace-cover/1600/600'),
('the-paper-tigers','The Paper Tigers','Four friends, loud guitars, and a stubborn love of choruses.','https://picsum.photos/seed/the-paper-tigers-artist/600/600','https://picsum.photos/seed/the-paper-tigers-cover/1600/600'),
('lo-fi-atlas','Lo-Fi Atlas','Dusty drum loops and tape-warped pianos for late study nights.','https://picsum.photos/seed/lo-fi-atlas-artist/600/600','https://picsum.photos/seed/lo-fi-atlas-cover/1600/600'),
('velvet-circuit','Velvet Circuit','House producer splicing disco strings into modular grooves.','https://picsum.photos/seed/velvet-circuit-artist/600/600','https://picsum.photos/seed/velvet-circuit-cover/1600/600'),
('orin-vale','Orin Vale','Folk storyteller from the north coast, one guitar, no filter.','https://picsum.photos/seed/orin-vale-artist/600/600','https://picsum.photos/seed/orin-vale-cover/1600/600'),
('saffron-echo','Saffron Echo','Global-pop collective blending tabla, trap and choir.','https://picsum.photos/seed/saffron-echo-artist/600/600','https://picsum.photos/seed/saffron-echo-cover/1600/600');
